// Offline QR generation: no third-party service or runtime network dependency.
import QRCode from "qrcode";

const codes = [1, 2, 3].map((id) => {
  const url = `https://x.kns.li/bd${id}`;
  const { modules } = QRCode.create(url, { version: 2, errorCorrectionLevel: "M" });
  return {
    url,
    rows: Array.from({ length: modules.size }, (_, y) =>
      Array.from({ length: modules.size }, (_, x) => modules.get(y, x) ? "1" : "0").join(""),
    ),
  };
});
await Bun.write(new URL("../src/birthdayQr.ts", import.meta.url),
  "// Generated by bun tools/gen-birthday-qr.ts (QR version 2, ECC M). Do not hand-edit.\n" +
  `export const BIRTHDAY_QR = ${JSON.stringify(codes, null, 2)} as const;\n`);
